#include "progress_monitor.h"
#include <math.h>
void progress_monitor_start(ProgressMonitor*m,GridPoint s,GridPoint t,uint64_t now){if(!m)return;*m=(ProgressMonitor){.start=s,.target=t,.best_distance_m=hypotf(t.x_m-s.x_m,t.y_m-s.y_m),.started_ms=now,.last_gain_ms=now,.active=true};}
ProgressResult progress_monitor_update(ProgressMonitor*m,const VehiclePose*p,uint64_t now,const AutonomyConfig*c){if(!m||!p||!c||!m->active||!p->valid||!isfinite(p->x_m)||!isfinite(p->y_m)||!isfinite(p->vx_mps)||!isfinite(p->vy_mps))return PROGRESS_INVALID;float d=hypotf(m->target.x_m-p->x_m,m->target.y_m-p->y_m);if(d<=c->subgoal_reached_tolerance_m){m->active=false;return PROGRESS_REACHED;}if(hypotf(p->vx_mps,p->vy_mps)>c->max_horizontal_speed_mps*1.5f)return PROGRESS_EXCESS_SPEED;if(d+c->progress_minimum_gain_m<m->best_distance_m){m->best_distance_m=d;m->last_gain_ms=now;}if(d>m->best_distance_m+c->progress_divergence_m)return PROGRESS_DIVERGED;if(now>=m->last_gain_ms&&now-m->last_gain_ms>=(uint64_t)(c->progress_timeout_s*1000.0f))return PROGRESS_STALLED;return PROGRESS_OK;}
